<div class="d-flex justify-content-between mb-4"><h1 class="h3">Tokens de API</h1><a class="btn btn-primary" href="/tokens/novo">Novo token</a></div><div class="alert alert-warning">O valor completo do token só será exibido uma vez após a criação.</div><div class="table-responsive"><table class="table table-bordered bg-white"><thead><tr><th>Nome</th><th>Escopos</th><th>Expiração</th><th>Último uso</th><th>Status</th><th>Ação</th></tr></thead><tbody><?php foreach ($tokens as $token): ?><tr><td><?= htmlspecialchars($token['nome'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($token['escopos'] ?: 'Nenhum definido', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($token['expira_em'] ?? 'Sem expiração', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($token['ultimo_uso_em'] ?? 'Nunca', ENT_QUOTES, 'UTF-8') ?></td><td><?= $token['revogado_em'] ? 'Revogado' : 'Ativo' ?></td><td><?php if (!$token['revogado_em']): ?><form method="post" action="/tokens/revogar"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int) $token['id'] ?>"><button class="btn btn-sm btn-outline-danger">Revogar</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?><?php if (!$tokens): ?><tr><td colspan="6" class="text-center text-muted">Nenhum token cadastrado.</td></tr><?php endif; ?></tbody></table></div><a href="/dashboard">Voltar ao dashboard</a>
